//! Required Option disabled boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><option id=option disabled=legacy value=one>One</option><option value=two>Two</option></select><datalist id=choices><option id=suggestion>Suggestion</option></datalist><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-disabled.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn option_disabled_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),P=HTMLOptionElement.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get disabled'||a.set.name!=='set disabled'||Object.hasOwn(x,'disabled')||x.disabled!==true||x.getAttribute('disabled')!=='legacy'||document.createElement('option').disabled!==false)throw 'canonical disabled boolean';"#);}
#[test]
fn option_disabled_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),old=x.getAttributeNode('disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.disabled=false;var records=watch.takeRecords();if(x.disabled!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='disabled')throw 'false removes actual attribute';var calls=0;x.disabled={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('disabled');records=watch.takeRecords();if(calls||x.disabled!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.disabled='';if(x.disabled!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}
#[test]
fn option_disabled_inert_exact_namespace_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:option');if(!(x instanceof HTMLOptionElement)||x.disabled!==false)throw 'inert absent disabled';x.setAttributeNS('urn:foreign','disabled','foreign');x.setAttributeNS(null,'DISABLED','upper');if(x.disabled!==false)throw 'exact disabled namespace and case';x.disabled=true;var attr=x.getAttributeNodeNS(null,'disabled');if(x.disabled!==true||attr===null||attr.value!=='')throw 'inert actual boolean';x.removeAttributeNS('urn:foreign','disabled');x.removeAttributeNS(null,'DISABLED');var clone=x.cloneNode(false),copy=x.cloneNode(false);if(!(clone instanceof HTMLOptionElement)||!(copy instanceof HTMLOptionElement)||clone.disabled!==true||copy.disabled!==true||copy.ownerDocument!==doc||clone.getAttributeNode('disabled')===attr)throw 'independent boolean copies';clone.disabled=false;if(x.disabled!==true||copy.disabled!==true||clone.disabled!==false)throw 'independent disabled removal';var caught=false;try{doc.importNode(x,false);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||x.disabled!==true||copy.disabled!==true||clone.disabled!==false||attr.ownerElement!==x||x.ownerDocument!==doc)throw 'inert option import lifecycle guard';"#);}

#[test]
fn option_disabled_truthiness_does_not_invoke_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),a=Object.getOwnPropertyDescriptor(HTMLOptionElement.prototype,'disabled'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.disabled!==false||x.hasAttribute('disabled'))throw 'false boolean value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('boolean'),BigInt(1),author]){a.set.call(x,value);if(x.disabled!==true||x.getAttribute('disabled')!==''||calls)throw 'true boolean value';}a.set.call(x);if(x.disabled!==false||calls)throw 'missing boolean argument';"#);}

#[test]
fn option_disabled_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'disabled getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'disabled setter brand';}Object.defineProperty(x,'disabled',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.disabled!=='author'||x.hasAttribute('disabled'))throw 'canonical attribute authority';delete x.disabled;if(x.disabled!==false||Object.hasOwn(x,'disabled'))throw 'restored inherited boolean';delete window.HTMLOptionElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}
#[test]
fn option_disabled_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.disabled=true;"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.disabled!==true||a.value!=='R\ud800'+key||x.getAttributeNode('disabled')!==a)throw 'raw boolean backing';}var old=a.value;x.disabled=true;var records=watch.takeRecords();if(x.disabled!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('disabled')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('disabled');if(x.disabled!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','disabled','foreign');x.setAttributeNS(null,'DISABLED','upper');if(x.disabled!==false)throw 'exact disabled authority';x.setAttributeNS(null,'disabled','A\udfffZ');if(x.ownerDocument!==document){var clone=x.cloneNode(false);if(!x.disabled||!clone.disabled||clone.getAttributeNodeNS(null,'disabled').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'disabled')===x.getAttributeNodeNS(null,'disabled'))throw 'raw presence copy';}"#);}}
#[test]
fn option_disabled_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOptionElement.prototype,'disabled');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-disabled.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://option-disabled.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.disabled!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('disabled')!=='')throw 'saved boolean recovery';");}

#[test]
fn option_disabled_writer_resource_refusal_is_atomic_and_recovers(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');"}else{"var x=document.getElementById('option');x.disabled=false;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.disabled=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.disabled!==false||watch.takeRecords().length)throw 'atomic disabled refusal';x.disabled=true;var records=watch.takeRecords();if(x.disabled!==true||x.getAttribute('disabled')!==''||records.length!==1||records[0].oldValue!==null)throw 'fresh boolean recovery';");}}}
#[test]
fn option_disabled_reads_charge_names_work_and_deadline_without_string_copy_or_retained_growth(){for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{let Value::Host(object)=p.runtime.execute("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.disabled=true;x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert OPTION")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("option")).unwrap())};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_disabled_get(object);if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_disabled_get(object),Ok(Value::Bool(true))));}}}
#[test]fn option_disabled_updates_actual_select_option_state_without_new_controls(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let count=f.controls.len();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),suggestion=document.getElementById('suggestion');x.disabled=false;suggestion.disabled=true;if(x.disabled||!suggestion.disabled)throw 'actual own disabled presence';");assert!(!f.controls[&select].select.as_ref().unwrap().options[0].disabled);assert_eq!(f.controls.len(),count);run(&mut d,&mut f,&mut p,"x.disabled=true;if(!x.disabled||x.getAttribute('value')!=='one')throw 'selected option disabled';");assert!(f.controls[&select].select.as_ref().unwrap().options[0].disabled);assert_eq!(f.controls.len(),count);}
